import Vue from 'vue'
import Router from 'vue-router'
import HomePage from '@/views/HomePage'
import AboutPage from '@/views/AboutPage'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'HomePage',
      component: HomePage
    },
    {
      path: '/school-overview',
      name: 'SchoolOverview',
      component: () => import('../views/SchoolOverview.vue')
    },
    {
      path: '/about',
      name: 'AboutPage',
      component: AboutPage
    },
   
  ]
})
